        "title": "أول قرار: هل البطاقة مفقودة فعلًا أم تالفة أم انتهت صلاحيتها؟",
        "paragraphs": [
          "عندما لا تجد بطاقة الرقم القومي، تأكد أولًا من أن المشكلة فقد فعلي للمستند وليست وجوده بحالة تلف تمنع استخدامه. فمراكز خدمات مصر تعرض «بدل فاقد رقم قومي» و«إصدار بطاقة رقم قومي بدل تالف» كخدمتين مستقلتين، كما يدرج دليل الخدمات العامة خدمة بدل التالف أو الفاقد. إذا كانت البطاقة لا تزال لديك لكن الكتابة غير واضحة أو جسمها مكسور، فابدأ بتحديد شروط التالف. وإذا كانت البطاقة موجودة ولكن انتهت صلاحيتها، فالتجديد معاملة مختلفة عن الفقد، ولا يصح اختيار سبب غير حقيقي لتسريع الطلب.",
          "اسأل نفسك هل تريد إعادة إصدار بطاقة فقدتها بالبيانات القائمة أم تريد أيضًا تغيير عنوان أو مهنة أو حالة اجتماعية. في الحالة الثانية لا تفترض أن مسار البدل يفتح لك تلقائيًا حق تعديل كل الحقول؛ بل افحص خدمات تحديث البيانات ومطلوباتها. لا تقدم طلبًا متسرعًا ثم تكتشف أن الوثيقة الجديدة تحمل عنوانًا قديمًا تحتاج تصحيحه. الهدف من اختيار السبب الصحيح هو الحصول على بديل مناسب مع احترام البيانات الرسمية، وليس فقط عبور شاشة الطلب."
        ],
        "bullets": [
          "فقدت البطاقة بالكامل: تحقق من خدمة بدل الفاقد.",
          "البطاقة موجودة ومتضررة: راجع بدل التالف.",
          "انتهاء الصلاحية أو تغير بيانات مهمة: افحص التجديد أو التحديث."
        ],
        "sourceUrls": [
          "https://www.khadamatmisr.gov.eg/node/62",
          "https://www.khadamatmisr.gov.eg/serviceslist",
          "https://psm.gov.eg/providers/1/services"
        ]
