          "إذا انتقلت إلى محافظة أخرى بعد الواقعة، اسأل هل يمكنك تقديم الطلب من محل إقامتك الحالي أو تحتاج الرجوع إلى موقع القيد الأصلي. لا تستعمل عنوانًا من إعلان تجاري باعتباره جهة التوثيق، ولا تعلن أن ورقة قديمة متاحة للتحميل من أي حساب دون تحقق. احتفظ باسم المكتب الذي وجهتك إليه الجهة الرسمية وقائمة المستندات التي طلبها. وإذا لم يتعرف النظام على الواقعة، فقد تحتاج إلى سؤال عن السجل الورقي أو قناة مختلفة."
